<?php if(!defined('ABSPATH'))exit; get_header(); ?>
<?php if(have_posts()): ?><div class="dg-list-heading"><span class="dg-kicker">مدرسه دانشگران</span><h1><?php if(is_search())echo 'نتایج جست‌وجو: '.esc_html(get_search_query());elseif(is_home())echo 'اخبار و اطلاعیه‌ها';else the_archive_title(); ?></h1></div><div class="dg-news-grid">
<?php while(have_posts()):the_post(); ?><article class="dg-card dg-story"><?php if(has_post_thumbnail()): ?><a href="<?php the_permalink(); ?>"><?php the_post_thumbnail('medium_large'); ?></a><?php endif; ?><div class="dg-story-body"><small><?php echo esc_html(get_the_date()); ?></small><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?><a class="dg-text-link" href="<?php the_permalink(); ?>">ادامه مطلب <?php echo dgt_icon('arrow'); ?></a></div></article><?php endwhile; ?></div><?php the_posts_pagination(); ?>
<?php else: ?><section class="dg-card dg-empty"><h1>هنوز مطلبی منتشر نشده است</h1><p>اخبار و اطلاعیه‌های مدرسه در این بخش نمایش داده می‌شوند.</p></section><?php endif; get_footer(); ?>
